import java.io.File;
import java.nio.file.Path;
import java.nio.file.Paths;

public class ImportingUtilities {

    // other methods

    /**
     * Creates a unique file inside {@code dir} using {@code name}. The method
     * protects against directory‑traversal attacks by normalizing the supplied
     * name and ensuring that the resolved path stays within {@code dir}.
     *
     * @param dir  the base directory where the file should be created
     * @param name the requested file name (may contain query parameters)
     * @return a {@link File} instance that does not yet exist
     * @throws IllegalArgumentException if the name would resolve outside {@code dir}
     */
    static public File allocateFile(File dir, String name) {
        if (dir == null || name == null) {
            throw new IllegalArgumentException("Directory and name must not be null");
        }

        // Strip query parameters
        int q = name.indexOf('?');
        if (q > 0) {
            name = name.substring(0, q);
        }

        // Normalise the supplied name to eliminate "..", ".", and redundant separators
        Path rawNamePath = Paths.get(name).normalize();

        // Reject absolute paths or paths that escape the target directory
        if (rawNamePath.isAbsolute()
                || rawNamePath.startsWith("..")
                || rawNamePath.toString().contains("..")) {
            throw new IllegalArgumentException(
                    "Invalid file name: path traversal detected");
        }

        // Resolve the name against the base directory and normalise again
        Path targetPath = dir.toPath().resolve(rawNamePath).normalize();

        // Ensure the resolved path is still under the base directory
        if (!targetPath.startsWith(dir.toPath().normalize())) {
            throw new IllegalArgumentException(
                    "Zip archives with files escaping their root directory are not allowed");
        }

        File file = targetPath.toFile();

        // Determine prefix and suffix for generating a unique name
        int dot = name.indexOf('.');
        String prefix = dot < 0 ? name : name.substring(0, dot);
        String suffix = dot < 0 ? "" : name.substring(dot);

        int index = 2;
        while (file.exists()) {
            file = new File(dir, prefix + "-" + index++ + suffix);
        }

        // Create any missing parent directories
        File parent = file.getParentFile();
        if (parent != null && !parent.exists()) {
            parent.mkdirs();
        }

        return file;
    }

    // other methods
}
```

