import javax.ws.rs.ext.RuntimeDelegate;
import java.util.regex.Pattern;

public class MediaTypeHeaderDelegate implements RuntimeDelegate.HeaderDelegate<javax.ws.rs.core.MediaType> {

    // --------------------------------------------------------------------
    // Whitelist-based validation for media‑type tokens.
    // --------------------------------------------------------------------
    // RFC 7230 § 3.2.6 defines a token as one or more of the following
    // characters:  !#$%&'*+-.^_`|~0-9A-Za-z
    // This excludes all control characters, whitespace, and separator
    // characters such as '/', ';', etc., thereby preventing header
    // injection via newline or carriage‑return characters.
    private static final Pattern TOKEN_PATTERN =
            Pattern.compile("[!#$%&'*+-.^_`|~0-9A-Za-z]+");

