private static String normalizePath(final String path) {
    // Preserve null values – callers expect null to propagate.
    if (path == null) {
        return null;
    }

    // Strip all leading '/' characters.
    int i = 0;
    while (i < path.length() && path.charAt(i) == '/') {
        i++;
    }

    // Build the normalized path with exactly one leading slash.
    // If the original path was composed solely of slashes, the result will be "/".
    String withoutLeading = path.substring(i);
    return "/" + withoutLeading;
}
