import com.opensymphony.xwork2.util.LocalizedTextUtil;
import org.apache.logging.log4j.LogManager;
import org.apache.logging.log4j.Logger;
import java.util.Locale;
import java.util.Set;
import java.util.HashSet;
import java.util.regex.Pattern;

/**
 * Interceptor responsible for handling internationalisation.
 */
public class I18nInterceptor extends AbstractInterceptor {

    protected static final Logger LOG = LogManager.getLogger(I18nInterceptor.class);

    /* --------------------------------------------------------------------- */
    /*  Locale validation helpers                                            */
    /* --------------------------------------------------------------------- */

    /** Regular expression that matches a valid ISO‑639 language tag
     *  optionally followed by an underscore and a two‑letter country code.
     *  Examples: "en", "en_US", "fr_CA". */
    private static final Pattern LOCALE_PATTERN =
            Pattern.compile("^[a-zA-Z]{2,3}(_[a-zA-Z]{2})?$");

    /** A set containing all locales supported by the JVM.  Used as a
     *  whitelist to reject unknown or malformed locale strings. */
    private static final Set<String> SUPPORTED_LOCALES = new HashSet<String>();

    static {
        for (Locale l : Locale.getAvailableLocales()) {
            SUPPORTED_LOCALES.add(l.toString());
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Public API                                                             */
    /* --------------------------------------------------------------------- */

    /**
     * Creates a {@link Locale} object from the request param, which might
     * already be a {@link Locale} or a {@code String}.  The method validates
     * the string representation against a whitelist of supported locales
     * to prevent injection of malicious values that could lead to XSS
     * vulnerabilities when the locale is later rendered in a view.
     *
     * @param requestedLocale the parameter from the request
     * @return the validated {@link Locale}, or {@code null} if the input
     *         is invalid or unsupported
     */
    protected Locale getLocaleFromParam(Object requestedLocale) {
        Locale locale = null;

        if (requestedLocale == null) {
            return null;
        }

        if (requestedLocale instanceof Locale) {
            locale = (Locale) requestedLocale;
        } else {
            String localeStr = requestedLocale.toString().trim();

            // Reject empty strings early
            if (localeStr.isEmpty()) {
                LOG.warn("Requested locale is an empty string");
                return null;
            }

            // Validate format using a strict regular expression
            if (!LOCALE_PATTERN.matcher(localeStr).matches()) {
                LOG.warn("Requested locale '{}' does not match expected pattern", localeStr);
                return null;
            }

            // Ensure the locale is actually supported by the JVM
            if (!SUPPORTED_LOCALES.contains(localeStr)) {
                LOG.warn("Requested locale '{}' is not supported by the JVM", localeStr);
                return null;
            }

            try {
                locale = LocalizedTextUtil.localeFromString(localeStr, null);
            } catch (IllegalArgumentException e) {
                LOG.warn("Failed to parse locale '{}': {}", localeStr, e.getMessage());
                return null;
            }
        }

        if (locale != null) {
            LOG.debug("Applied request locale: {}", locale);
        }

        return locale;
    }

    // other methods
}
