        // Reject invalid action names outright
        if (LOG.isWarnEnabled()) {
            LOG.warn("Action/method [{}] does not match allowed action names pattern [{}], rejecting it.",
                     trimmed, allowedActionNames.pattern());
        }

        // Return a safe default action name instead of attempting partial sanitisation
        return "default";
    }

