    try {
        ctx = new InitialLdapContext(env, null);
        StartTlsRequest startTlsRequest = new StartTlsRequest();
        StartTlsResponse tls = (StartTlsResponse) ctx.extendedOperation(startTlsRequest);
        tls.negotiate();

        // Rebind with credentials over TLS
        env.put(Context.SECURITY_AUTHENTICATION, jndiLdapContextFactory.getAuthenticationMechanism());
        env.put(Context.SECURITY_PRINCIPAL, principal);
        env.put(Context.SECURITY_CREDENTIALS, credentials);
        // Close previous context and create new one with TLS enabled
        ctx.close();
        ctx = new InitialLdapContext(env, null);
        // Verify authentication by performing a simple lookup
        ctx.lookup(""); // root
