            // Reject names that start with a separator or contain ".." after normalisation
            if (sanitizedName.startsWith(File.separator) || sanitizedName.contains("..")) {
                throw new IOException("Archive entry name '" + rawName + "' is invalid (potential path traversal)");
            }

            // Resolve the destination path and normalize it
            Path destPath = targetDirPath.resolve(sanitizedName).normalize();

            // Ensure the destination is still within the target directory
            if (!destPath.startsWith(targetDirPath)) {
                throw new IOException("Expanding entry '" + rawName + "' would create file outside of "
                        + targetDirectory.getAbsolutePath());
            }

            File destFile = destPath.toFile();

            if (nextEntry.isDirectory()) {
                if (!destFile.isDirectory() && !destFile.mkdirs()) {
                    throw new IOException("Failed to create directory " + destFile);
                }
            } else {
                // Ensure parent directories exist
                File parent = destFile.getParentFile();
                if (parent != null && !parent.isDirectory() && !parent.mkdirs()) {
                    throw new IOException("Failed to create directory " + parent);
                }

                // Write the file contents
                try (OutputStream out = Files.newOutputStream(destPath, LinkOption.NOFOLLOW_LINKS)) {
                    writer.writeEntryDataTo(nextEntry, out);
                }
            }

            nextEntry = supplier.getNextReadableEntry();
        }
